"""Fixtures for the Go gateway's cluster-state tools (A-9 S5c: airframe.status, airframe.describe, airframe.verify), generated by
driving the Python AirframeTools (airframe_tools.py) over a real KubeReader (airframe_api.py) whose transport is a fake Kubernetes
API server: the requests the reader sent (path and query, as the API server saw them) with the answer each got, and what the tool
returned, refused or raised.

gateway/internal/airframe/testdata/state.json is read by the Go test state_python_test.go, which serves the recorded answers from an
httptest server through backends.KubeReader (so the closed list of reads is what is tested too) and requires the same result and
the same MULTISET of requests: Python lists the kinds of a namespace in parallel, so the order of those requests is not fixed and the
fixture holds them sorted.

A case may carry "go": a different expectation for Go (its own requests and result), with "why": the places Go is deliberately
stricter than Python.

Called by tools/gen_gateway_airframe.py (outputs()), whose --check fails when a committed file differs.
"""
from __future__ import annotations

import json
import sys
import tempfile
import threading
import urllib.parse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))

from autopilot import airframe_plan  # noqa: E402
from autopilot.airframe_api import AirframeError, KubeReader, PathRefused, argo_path, xr_path  # noqa: E402
from autopilot.airframe_tools import CONTRACT, AirframeTools  # noqa: E402
from autopilot.engine.dispatch import Denied  # noqa: E402

OUT = ROOT / "gateway" / "internal" / "airframe" / "testdata" / "state.json"
SERVER = "https://k.invalid"
PLURAL = {k: v["plural"] for k, v in CONTRACT["xrds"].items()}
REG = airframe_plan.Registry("kind-dev", ("kind-prod",), "gitops-cluster-dev-tenants")


def path_of(obj: dict) -> str:
    md = obj["metadata"]
    if obj["kind"] == "Application":
        return argo_path("applications", md["namespace"], md["name"])
    if obj["kind"] == "Rollout":
        return argo_path("rollouts", md["namespace"], md["name"])
    return xr_path(PLURAL[obj["kind"]], md["namespace"], md["name"])


class World:
    """A fake API server over a set of objects: a GET of an object path answers the object or 404, a GET of a list path the
    objects below it that match labelSelector, a page at a time when `pages` says so. `status` overrides the answer of a path."""

    def __init__(self, objects=(), status=None, pages=None, raw=None):
        self.objects = {path_of(o): o for o in objects}
        self.status, self.pages, self.raw = status or {}, pages or {}, raw or {}
        self.seen: list[dict] = []
        self.lock = threading.Lock()

    def opener(self, req, timeout, ctx):
        u = urllib.parse.urlsplit(req.full_url)
        q = dict(urllib.parse.parse_qsl(u.query, keep_blank_values=True))
        target = u.path + (("?" + u.query) if u.query else "")
        path = u.path
        status, body = 200, None
        if path in self.status:
            status, body = self.status[path], {"kind": "Status", "message": "from the fixture"}
        elif path in self.raw:
            body = self.raw[path]
        elif path in self.objects:
            body = self.objects[path]
        else:
            parent_items = sorted(((p, o) for p, o in self.objects.items() if p.rsplit("/", 1)[0] == path))
            seg = path.rsplit("/", 1)[-1]
            is_list = path.count("/") == 6 and (seg in PLURAL.values() or seg in ("applications", "rollouts"))
            if is_list:
                sel = dict(kv.split("=", 1) for kv in q["labelSelector"].split(",")) if q.get("labelSelector") else {}
                items = [o for _, o in parent_items
                         if all((o["metadata"].get("labels") or {}).get(k) == v for k, v in sel.items())]
                body = {"items": items}
                n = self.pages.get(path)
                if n:
                    off = int(q.get("continue") or 0)
                    body = {"items": items[off:off + n]}
                    if off + n < len(items):
                        body["metadata"] = {"continue": str(off + n)}
            else:
                status, body = 404, {"kind": "Status", "reason": "NotFound"}
        raw = body if isinstance(body, bytes) else json.dumps(body).encode()
        with self.lock:
            self.seen.append({"target": target, "status": status, "body": json.loads(raw) if raw else None})
        return status, raw


def xr(kind, ns, name, gen=1, conds=(), spec=None, status=None, labels=None):
    md = {"name": name, "namespace": ns, "generation": gen}
    if labels:
        md["labels"] = labels
    st = dict(status or {})
    if conds is not None:
        st["conditions"] = [dict(c) for c in conds]
    return {"apiVersion": "catalog.hangar.io/v1alpha1", "kind": kind, "metadata": md, "spec": spec or {}, "status": st}


def c(type_, status="True", reason=None, message=None, obs=None):
    out = {"type": type_, "status": status}
    if reason is not None:
        out["reason"] = reason
    if message is not None:
        out["message"] = message
    if obs is not None:
        out["observedGeneration"] = obs
    return out


def app_obj(name, ns, app, env, resources=(), labels=None, spec=None, status=None):
    lab = {"hangar.io/app": app, "hangar.io/env": env, **(labels or {})}
    return {"apiVersion": "argoproj.io/v1alpha1", "kind": "Application", "metadata": {"name": name, "namespace": ns, "labels": lab},
            "spec": spec or {"project": f"{app}-lower", "destination": {"server": "https://kubernetes.default.svc", "namespace": f"app-{app}-{env}"},
                             "sources": [{"repoURL": f"https://github.com/o/gitops-{app}", "path": f"{env}", "targetRevision": "main"},
                                         {"repoURL": f"https://github.com/o/{app}", "targetRevision": "HEAD"}]},
            "status": status or {"sync": {"status": "Synced", "revisions": ["a" * 40, "b" * 40]},
                                 "health": {"status": "Healthy", "message": "ok"},
                                 "operationState": {"phase": "Succeeded", "message": "done", "finishedAt": "2026-11-14T10:00:00Z"},
                                 "reconciledAt": "2026-11-14T10:01:00Z", "resources": list(resources)}}


def rollout(name, ns, gen=3, obs="3", phase="Healthy", strategy=None, images=("ghcr.io/o/shop:1",)):
    return {"apiVersion": "argoproj.io/v1alpha1", "kind": "Rollout", "metadata": {"name": name, "namespace": ns, "generation": gen},
            "spec": {"replicas": 2, "strategy": strategy or {"canary": {"steps": []}},
                     "template": {"spec": {"containers": [{"name": "app", "image": i} for i in images]}}},
            "status": {"phase": phase, "message": "m" * 400 if phase == "Degraded" else "", "readyReplicas": 2, "availableReplicas": 2,
                       "updatedReplicas": 2, "currentStepIndex": 1, "stableRS": "abc", "currentPodHash": "def", "observedGeneration": obs}}


def shop_world():
    ns = "app-shop-cicd"
    return [
        xr("PythonApplication", ns, "shop", 3, [c("Synced", "True", "ReconcileSuccess", obs=3), c("Ready", "True", "Available", obs=3),
                                                c("CicdOnboarded", "True", "Onboarded")]),
        xr("TektonCICD", ns, "shop-cicd", 2, [c("Synced", "True", "ReconcileSuccess", obs=2), c("Ready", "False", "Creating", "waiting " + "x" * 400, obs=2)]),
        xr("SecretStore", ns, "shop-store", 1, [c("Synced", "False", "ReconcileError", 'cluster registry record "hangar-dev" has no infisicalUrl/infisicalOrgId')]),
        xr("ApplicationEnvironment", ns, "shop-kind-dev-dev", 1, [c("Ready", "True")], spec={"appName": "shop", "cluster": "kind-dev", "env": "dev"}),
        xr("ApplicationEnvironment", ns, "shop-kind-prod-prod", 1, [c("Ready", "True")], spec={"appName": "shop", "cluster": "kind-prod", "env": "prod"}),
        xr("ApplicationEnvironment", ns, "shop-kind-dev-hot", 1, [c("Ready", "True")], spec={"appName": "shop", "cluster": "kind-dev", "env": "hot"}),
        xr("PostgreSQL", "app-shop-dev", "shop-db", 5, [c("Synced", "True", "ReconcileSuccess", obs=3), c("Ready", "False", "Creating", obs=2),
                                                         c("ComponentReady", "False", "ClusterNotReady", "not yet")]),
        xr("PostgreSQL", "app-shop-hot", "shop-db", 2, [c("Synced", "False", "ReconcileError", 'failed calling webhook "mutate.cnpg.io": no endpoints')]),
        xr("Redis", "app-shop-hot", "shop-cache", 2, [c("Synced", "False", "ReconcileError", 'failed calling webhook "x.example.com"'),
                                                       c("Ready", "Unknown")]),
        app_obj("shop-dev", "argocd-apps", "shop", "dev", [{"kind": "Rollout", "group": "argoproj.io", "namespace": "app-shop-dev", "name": "shop"},
                                                           {"kind": "Service", "group": "", "namespace": "app-shop-dev", "name": "shop"}]),
        rollout("shop", "app-shop-dev", 5, "4"),
        app_obj("shop-hot", "argocd-apps", "shop", "hot", [{"kind": "Rollout", "group": "argoproj.io", "namespace": "app-shop-hot", "name": "shop"}]),
        rollout("shop", "app-shop-hot", 5, "x", "Degraded", {"blueGreen": {}}, ("a:1", "b:2")),
        app_obj("shop-pr-12", "app-shop-cicd", "shop", "pr-12", [], labels={"hangar.io/ephemeral-env": "true"},
                spec={"project": "p", "source": {"repoURL": "https://x", "path": "p", "targetRevision": "main"}},
                status={"sync": {"status": "OutOfSync", "revision": "c" * 40}, "health": {"status": "Progressing", "message": "h" * 500}}),
        rollout("shop", "app-shop-xx", 1, "1"),
        rollout("shop", "app-shop-nomatch", 1, "1"),
    ]


def other_worlds():
    return {
        "infra": [xr("InfraService", "infra-tool-cicd", "tool", 1, [c("Ready", "True")]),
                  xr("ManagedPostgreSQL", "infra-tool-dev", "tool-db", 1, [c("Ready", "True")])],
        "weird": [{"apiVersion": "catalog.hangar.io/v1alpha1", "kind": "PythonApplication",
                   "metadata": {"name": "w", "namespace": "app-weird-cicd"},
                   "status": {"conditions": ["junk", None, {"type": "Ready", "status": "True"}, {"type": "Odd", "status": "False", "reason": "R"}]}},
                  {"apiVersion": "catalog.hangar.io/v1alpha1", "kind": "Redis", "metadata": {"name": "r", "namespace": "app-weird-cicd"}}],
        "paged": [xr("PythonApplication", "app-pg-cicd", f"pg{i}", 1, [c("Ready", "True")]) for i in range(3)],
    }


def run(world: World, tool: str, *args):
    with tempfile.TemporaryDirectory() as td:
        tok = Path(td) / "token"
        tok.write_text("fixture-token")
        tools = AirframeTools(KubeReader(SERVER, tok, opener=world.opener), None, REG, cluster="hangar-dev")
        try:
            out = getattr(tools, tool)(*args)
            return {"result": out}
        except Denied as e:
            return {"error": {"class": "Denied", "rule": e.rule, "message": e.message, "hint": e.hint}}
        except AirframeError as e:
            return {"error": {"class": "AirframeError", "message": str(e)}}


def case(name, objects, tool, args, status=None, pages=None, go=None, why=None):
    w = World(objects, status, pages)
    out = run(w, tool, *args)
    reqs = sorted(w.seen, key=lambda r: (r["target"], r["status"]))
    d = {"name": name, "tool": tool, "args": list(args), "requests": reqs, **out}
    if status:
        d["status"] = {k: v for k, v in status.items()}
    if go:
        d["go"], d["why"] = go, why
    return d


def verify_cases():
    cases = []
    every = {**CONTRACT["components"], **CONTRACT.get("targets", {}), **CONTRACT["kinds"]}
    for key, sc in sorted(every.items()):
        kind = sc["kind"]
        if not sc.get("verify"):
            continue
        ns = "app-vx-cicd"
        status_full = {"cluster": "c", "service": "s", "region": "us-east-1", "functionName": "f", "functionUrl": "https://f.example/",
                       "url": "https://q.example/", "appName": "a", "resourceGroup": "rg", "serverName": "srv", "bucketName": "b",
                       "rolloutPhase": "Healthy", "phase": "Running", "commit": "abc"}
        every_cond = ["Synced", "Ready"] + [cd["type"] for cd in sc.get("conditions") or []]
        variants = {
            "bare": xr(kind, ns, "x1", 2, [c("Synced", "True", "ReconcileSuccess", obs=2), c("Ready", "True", "Available", obs=2)]),
            "full": xr(kind, ns, "x1", 2, [c(t, "True", (((sc.get("conditions") or [{}])[0].get("reasons") or [{}])[0]).get("reason")
                                             if t not in ("Synced", "Ready") else "ReconcileSuccess", obs=2) for t in every_cond],
                       spec={"mode": "attach", "target": {"enabled": True}, "region": "us-east-1", "appName": "vx", "source": {"commit": "abc"}},
                       status=status_full),
            "broken": xr(kind, ns, "x1", 4, [c("Synced", "False", "ReconcileError", 'failed calling webhook "mutate.cnpg.io"', obs=2),
                                             c("Ready", "False", "Creating", "m" * 400, obs=3)]
                         + [c(cd["type"], "False", "NoSuchReason", "bad", obs=1) for cd in (sc.get("conditions") or [])[:2]],
                         spec={"mode": "server", "target": {"enabled": False}}, status={"phase": "Pending", "rolloutPhase": "Degraded", "commit": "zzz"}),
            "nosync": xr(kind, ns, "x1", 1, None, spec={"mode": "broker"}),
        }
        for vname, x in variants.items():
            cs = case(f"verify {kind} {vname}", [x], "verify", ["vx", kind, "x1"])
            if kind == "Agent":
                # Agent XRs are read by the definition loader's list only; Go has no read of one by name.
                e = PathRefused(xr_path("agents", "app-vx-cicd", "x1"))
                cs["go"] = {"requests": [], "error": {"class": "Denied", "rule": e.rule, "message": e.message, "hint": e.hint}}
                cs["why"] = ("an Agent XR is listed (the definition loader) and never read by name: the closed list of reads has no "
                             "request for it, so verify of an Agent is refused before any request")
            cases.append(cs)
    return cases


def all_cases():
    shop, other = shop_world(), other_worlds()
    cs = []
    cs.append(case("status: the app", shop, "status", ["shop"]))
    cs.append(case("status: a Flight environment (its ApplicationEnvironment, no XRs in its namespace)", shop, "status", ["shop", "prod"]))
    cs.append(case("status: a Ground environment with XRs", shop, "status", ["shop", "dev"]))
    cs.append(case("status: a webhook failure, a redis", shop, "status", ["shop", "hot"]))
    cs.append(case("status: an environment nothing is known of", shop, "status", ["shop", "stage"]))
    cs.append(case("status: an empty environment name", shop, "status", ["shop", ""]))
    cs.append(case("status: an infra app", other["infra"], "status", ["tool", "dev"]))
    cs.append(case("status: conditions of the wrong shapes", other["weird"], "status", ["weird"]))
    cs.append(case("status: no such app", shop, "status", ["nope"]))
    cs.append(case("status: no such app (an environment named)", shop, "status", ["nope", "dev"]))
    cs.append(case("status: a list in pages", other["paged"], "status", ["pg"],
                   pages={"/apis/catalog.hangar.io/v1alpha1/namespaces/app-pg-cicd/pythonapplications": 2}))
    bad = ["A/B", "Shop", "..", "x%2fy", "a" * 300, "a_b", "é", "a b", "a\nb", "a\x00b", "", "-x", "x-"]
    for a in bad:
        cs.append(case(f"status: app {a!r:.40} is not a name", shop, "status", [a]))
    for e in ["A", "../x", "a/b", "e" * 70, "é", "a%2fb", "a b"]:
        cs.append(case(f"status: environment {e!r:.40} is not a name", shop, "status", ["shop", e]))
    cs.append(case("status: the API server refuses Clearance", shop, "status", ["shop"],
                   status={"/apis/catalog.hangar.io/v1alpha1/namespaces/app-shop-cicd/redis": 403}))
    cs.append(case("status: the API server fails", shop, "status", ["shop"],
                   status={"/apis/catalog.hangar.io/v1alpha1/namespaces/app-shop-cicd/slos": 500}))
    cs.append(case("describe: a Ground environment, its Application and its Rollout", shop, "describe", ["shop", "dev"]))
    cs.append(case("describe: a Degraded Rollout with two images and a Blue-Green strategy", shop, "describe", ["shop", "hot"]))
    cs.append(case("describe: an ephemeral environment (an Application in the cicd namespace, one source)", shop, "describe", ["shop", "pr-12"]))
    cs.append(case("describe: a Flight environment on another cluster", shop, "describe", ["shop", "prod"]))
    cs.append(case("describe: no Application and no XRs: the Rollouts of the namespace", shop, "describe", ["shop", "stage"]))
    cs.append(case("describe: no such app", shop, "describe", ["nope", "dev"]))
    cs.append(case("describe: an infra app", other["infra"], "describe", ["tool", "dev"]))
    cs.append(case("describe: a Rollout the Application names that is gone", [o for o in shop if o["kind"] != "Rollout"], "describe", ["shop", "dev"]))
    foreign = [app_obj("shop-dev", "argocd-apps", "shop", "dev", [{"kind": "Rollout", "group": "argoproj.io", "namespace": "app-other-dev", "name": "x"}]),
               rollout("x", "app-other-dev", 1, "1")] + [o for o in shop if o["kind"] not in ("Rollout", "Application")]
    py_foreign = case("describe: an Application names a Rollout in another app's namespace", foreign, "describe", ["shop", "dev"])
    r = json.loads(json.dumps(py_foreign))
    r["requests"] = [q for q in r["requests"] if "/rollouts/x" not in q["target"]]
    r["result"]["rollouts"] = []
    py_foreign["go"] = {"requests": r["requests"], "result": r["result"]}
    py_foreign["why"] = ("an Application's resource list is written from a tenant's manifests: a Rollout is read only in this "
                         "environment's own namespace (<type>-<app>-<env>), never in another app's")
    cs.append(py_foreign)
    cs.append(case("describe: the API server refuses Clearance on Applications", shop, "describe", ["shop", "dev"],
                   status={"/apis/argoproj.io/v1alpha1/namespaces/argocd-apps/applications": 403}))
    cs.append(case("describe: environment not a name", shop, "describe", ["shop", "A/B"]))
    cs.append(case("verify: an unknown kind", shop, "verify", ["shop", "Nonesuch", "x"]))
    cs.append(case("verify: an XR that is not there", shop, "verify", ["shop", "PythonApplication", "nope"]))
    cs.append(case("verify: an XR that is not there in an environment", shop, "verify", ["shop", "PostgreSQL", "nope", "dev"]))
    cs.append(case("verify: the app's own XR", shop, "verify", ["shop", "PythonApplication", "shop"]))
    cs.append(case("verify: an environment XR", shop, "verify", ["shop", "postgresql", "shop-db", "dev"]))
    cs.append(case("verify: by plural", shop, "verify", ["shop", "pythonapplications", "shop"]))
    cs.append(case("verify: an infra app's XR", other["infra"], "verify", ["tool", "InfraService", "tool"]))
    cs.append(case("verify: a failing known failure", shop, "verify", ["shop", "SecretStore", "shop-store"]))
    cs.append(case("verify: a webhook failure", shop, "verify", ["shop", "Redis", "shop-cache", "hot"]))
    for a in ["A/B", "..", "x%2fy", "é", "a" * 300]:
        cs.append(case(f"verify: app {a!r:.40} is not a name", shop, "verify", [a, "PythonApplication", "shop"]))
    for n in ["A/B", "..", "x%2fy", "é", "n" * 300, "a b"]:
        cs.append(case(f"verify: name {n!r:.40} is not a name", shop, "verify", ["shop", "PythonApplication", n]))
    cs.append(case("verify: the API server fails", shop, "verify", ["shop", "PythonApplication", "shop"],
                   status={"/apis/catalog.hangar.io/v1alpha1/namespaces/app-shop-cicd/pythonapplications/shop": 500}))
    cs += verify_cases()
    return cs


def outputs() -> dict:
    lines = ",\n".join(json.dumps(c, sort_keys=True, separators=(",", ":")) for c in all_cases())
    return {OUT: '{"cases":[\n' + lines + "\n]}\n"}


if __name__ == "__main__":
    for p, t in outputs().items():
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(t)
        print(p, len(json.loads(t)["cases"]), "cases")
